        solve = solve.slice(0, solve.length - 1);
        solve += "dot";
    } else if (solve[solve.length - 1] === '@') {
        solve = solve.slice(0, solve.length - 1);
        solve += "at";
    }
}

function main() {
    for (let I = 0; I < N; ++I) {
        if (I + 3 <= N) {
            if (s.substr(I, 3) === "dot") {
                solve += ".";
                I += 2;
            } else {
                if (I + 2 <= N) {
                    if (s.substr(I, 2) === "at") {
                        solve += "@";
                        I += 1;
                    } else solve += s[I];
                } else solve += s[I];
            }
        } else if (I + 2 <= N) {
            if (s.substr(I, 2) === "at") {
                solve += "@";
                I += 1;
            } else solve += s[I];
        } else solve += s[I];
    }

    Check();

    let cont = 0;

    for (let I = 0; I < solve.length; ++I) {
        if (solve[I] === '@') ++cont;
    }

    let out = "";

    if (cont === 1) out += solve + "\n";
    else {
        let ok = true;

        for (let I = 0; I < solve.length; ++I) {
            if (solve[I] === '@') {
                if (ok) {
                    out += '@';
                    ok = false;
                } else {
                    out += "at";
                }
                continue;
            }
            out += solve[I];
        }
        out += "\n";
    }

    process.stdout.write(out);
}

main();
